    [273085] = {"|cff1eff00Blueprint: Fermenter|r"," ","|cffffffffFermenter|r","Requires Alchemy (140)","|cff1eff00Use: Places a fermenter that allows the creation of certain reagents, and provides all of the benefits of a Mana Well. Requires a Campfire nearby.|r","|cff1eff00May be placed over a Mana Well to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)|r","Use: Teaches you how to place a Fermenter at a campsite.","Craft a Fermenter.","Requires Alchemy (140)"},
    [273086] = {"|cff1eff00Blueprint: Anvil|r"," ","|cffffffffAnvil|r","Requires Blacksmithing (140)","|cff1eff00Use: Places an anvil, and provides all of the benefits of a Sharpening Wheel. Requires a Campfire nearby.|r","|cff1eff00May be placed over a Sharpening Wheel to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)|r","Use: Teaches you how to place an Anvil at a campsite.","Craft an Anvil.","Requires Blacksmithing (140)"},
    [273087] = {"|cff1eff00Blueprint: Journeyman Campfire|r"," ","|cffffffffJourneyman Campfire Kit|r","Requires Cooking (140)","|cff1eff00Use: Builds a journeyman campfire that allows cooking and the placement of up to 5 additional camp features. Players sitting or crafting nearby for 1 min will gain benefits from other camp features. (5 Min Cooldown)|r","Use: Teaches you how to place a Journeyman Campfire at a campsite.","Craft a Journeyman Campfire.","Requires Cooking (90)"},
    [273092] = {"|cff1eff00Blueprint: Repair Bot|r"," ","|cffffffffRepair Bot|r","Requires Engineering (140)","|cff1eff00Use: Summons a Repair Bot that allows you and others nearby to buy reagents and repair gear. Requires a Campfire nearby.|r","|cff1eff00May be placed over a Reagent Bot to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)|r","Use: Teaches you how to place a Repair Bot at a campsite.","Craft a Repair Bot.","Requires Engineering (140)"},
    [273096] = {"|cff1eff00Blueprint: Tanning Rack|r"," ","|cffffffffTanning Rack|r","Requires Leatherworking (140)","|cff1eff00Use: Places a Tanning Rack that allows the creation of certain reagents, and provides all of the benefits of a Camp Tent. Requires a Campfire nearby.|r","|cff1eff00May be placed over a Camp Tent to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)|r","Use: Teaches you how to place a Tanning Rack at a campsite.","Craft a Tanning Rack.","Requires Leatherworking (140)"},
    [273097] = {"|cff1eff00Blueprint: Rock Garden|r"," ","|cffffffffRock Garden|r","Requires Mining (140)","|cff1eff00Use: Places a Rock Garden that spawns a common mining node over time, and provides all the benefits of a Lodestone. Requires a Campfire nearby.|r","|cff1eff00May be placed over a Lodestone to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)|r","Use: Teaches you how to place a Rock Garden at a campsite.","Craft a Rock Garden.","Requires Mining (140)"},
    [273098] = {"|cff1eff00Blueprint: Field Guide|r"," ","|cffffffffField Guide|r","Requires Skinning (140)","|cff1eff00Use: Places a Field Guide that allows players to read it and gain Track Beasts, and provides all the benefits of a Camp Chair. Requires a Campfire nearby.|r","|cff1eff00May be placed over a Camp Chair to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)|r","Use: Teaches you how to place a Field Guide at a campsite.","Craft a Field Guide.","Requires Skinning (140)"},
    [273099] = {"|cff1eff00Blueprint: Spinning Wheel|r"," ","|cffffffffSpinning Wheel|r","Requires Tailoring (140)","|cff1eff00Use: Places a Spinning Wheel that allows the creation of certain reagents, and provides all the benefits of a Faction Banner. Requires a Campfire nearby.|r","|cff1eff00May be placed over a Faction Banner to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)|r","Use: Teaches you how to place a Spinning Wheel at a campsite.","Craft a Spinning Wheel.","Requires Tailoring (140)"},
    [273102] = {"|cff1eff00Blueprint: Cookie's Feast|r"," ","|cffffffffCookie's Feast|r","Requires Cooking (140)","|cff1eff00Use: Lay out Cookie's Feast that contains Stamina-boosting food.|r","|cff1eff00Requires a Cooking Fire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)|r","Use: Teaches you how to place Cookie's Feast at a campsite.","Craft Cookie's Feast.","Requires Cooking (140)"},
    [273103] = {"|cff1eff00Blueprint: Arcane Salvager|r"," ","|cffffffffArcane Salvager|r","Requires Enchanting (140)","|cff1eff00Use: Places an Arcane Salvager that enables more efficient disenchanting, and provides all the benefits of an Enchanted Lute. Requires a Campfire nearby.|r","|cff1eff00May be placed over an Enchanted Lute to replace it.|r","|cff1eff00All camping features share a cooldown of 1 hour. (1 Hour Cooldown)|r","Use: Teaches you how to place an Arcane Salvager at a campsite.","Craft an Arcane Salvager.","Requires Enchanting (140)"},
